<template><view class="page">
<view class="steps"><view :class="step===1?'active':''">① 基本信息</view><view :class="step===2?'active':''">② 考试设置</view><view>③ 完成</view></view><view class="title">{{step===1?'选择考试类型':'设置你的学习安排'}}</view>
<view v-if="error" class="error">{{error}}</view>
<template v-if="step===1"><view class="card"><view class="type-grid"><view v-for="(t,i) in types" :key="t.code" :class="['choice','type-'+i,form.examType===t.code?'chosen':'']" @click="choose(t)"><view class="type-symbol">{{t.symbol||t.name.slice(0,1)}}</view><view>{{t.name}}</view><text v-if="form.examType===t.code" class="tick">✓</text></view></view></view><button class="primary" :disabled="!form.examType" @click="step=2">下一步</button></template>
<template v-else><view class="card"><view class="field"><text class="label">考试名称</text><input class="input" v-model="form.examName" maxlength="80" placeholder="例如：2027考研"/></view><view class="field"><text class="label">考试日期</text><picker mode="date" :value="form.examDate" :start="minDate" :end="maxDate" @change="form.examDate=$event.detail.value"><view class="input">{{form.examDate}}　⌄</view></picker><view class="muted">请按实际考试通知填写日期</view></view><view class="field"><text class="label">每天可学习时间（分钟）</text><input class="input" type="number" v-model="minutes" placeholder="30至720分钟"/></view><view class="field"><text class="label">当前基础</text><view class="levels"><view v-for="l in levels" :key="l.value" :class="form.level===l.value?'active':''" @click="form.level=l.value">{{l.name}}</view></view></view></view>
<view class="card"><view class="row"><text class="section">科目与学习权重</text><text class="link" @click="addSubject">＋添加</text></view><view class="muted">按实际考试科目修改，权重决定时间分配。</view><view v-for="(s,i) in form.subjects" :key="i" class="subject-row"><input class="input subject-name" v-model="s.name" maxlength="80" placeholder="科目名称"/><input class="input subject-weight" type="number" v-model="s.weight"/><text class="remove" @click="form.subjects.splice(i,1)">×</text></view></view>
<view class="notice">模板提供通用学习路线。请结合考试大纲和个人教材安排具体知识点。</view><view class="row"><button class="secondary" :disabled="saving" @click="step=1">上一步</button><button class="primary grow" :disabled="saving" @click="submit">{{saving?'正在生成计划…':'生成我的计划 →'}}</button></view></template>
<view v-if="saving" class="generating"><image src="/static/dengkemiao.png"/><view class="title">正在安排你的备考路线</view><view class="muted">计算剩余时间 · 分配科目时长 · 生成阶段任务</view></view>
</view></template>
<script setup>
import {ref,reactive} from 'vue';import {onLoad} from '@dcloudio/uni-app';import {api} from '../../api';import {generate,today,addDays} from '../../utils/planner.mjs'
const step=ref(1),types=ref([]),error=ref(''),saving=ref(false),minutes=ref('240'),minDate=addDays(today(),1),maxDate=addDays(today(),730)
const levels=[{value:'weak',name:'基础薄弱'},{value:'normal',name:'基础一般'},{value:'good',name:'基础较好'}]
const form=reactive({examType:'',examName:'',examDate:addDays(today(),180),dailyMinutes:240,level:'normal',subjects:[]})
function choose(t){form.examType=t.code;form.examName=t.name+'备考';form.subjects=t.subjects.map(s=>({...s}))}
onLoad(async options=>{try{types.value=await api.templates();const t=types.value.find(t=>t.code===options.type);if(t){choose(t);step.value=2}}catch(e){error.value=e.message}})
function addSubject(){if(form.subjects.length>=8)return;form.subjects.push({name:'',weight:20})}
async function submit(){error.value='';const input={...form,dailyMinutes:Number(minutes.value),subjects:form.subjects.map(s=>({name:s.name.trim(),weight:Number(s.weight)}))};try{generate(input);saving.value=true;await api.create(input);uni.redirectTo({url:'/pages/plan/generated'})}catch(e){error.value=e.message}finally{saving.value=false}}
</script>
<style scoped>.title{margin-top:10rpx}.steps{display:flex;gap:24rpx;margin:30rpx 0;color:#9AA8BB;font-size:25rpx}.steps view{flex:1;padding:16rpx;border-bottom:5rpx solid #DFE7F2}.steps .active{color:#1677FF;border-color:#1677FF}.choice{border:2rpx solid transparent}.choice .section{margin:0 0 8rpx}.chosen{border-color:#1677FF;background:#F0F7FF}.levels{display:flex;gap:12rpx}.levels view{flex:1;text-align:center;background:#F4F7FC;border-radius:14rpx;padding:16rpx 8rpx;font-size:24rpx}.levels .active{background:#EAF4FF;color:#1677FF}.subject-row{display:flex;align-items:center;gap:12rpx;margin-top:18rpx}.subject-name{flex:1;min-width:0}.subject-weight{width:120rpx}.remove{font-size:38rpx;color:#A1ADBF;padding:8rpx}.grow{flex:1}.generating{position:fixed;inset:0;background:#F6F9FFF5;z-index:90;display:flex;flex-direction:column;align-items:center;justify-content:center;text-align:center;padding:40rpx}.generating image{width:180rpx;height:180rpx;border-radius:50%;margin-bottom:35rpx}</style>
<style scoped>.title{font-size:31rpx;margin:20rpx 0}.steps{font-size:22rpx;gap:10rpx;margin-top:12rpx}.steps view{padding:12rpx 4rpx;text-align:center}.type-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16rpx}.choice{position:relative;text-align:center;border:2rpx solid transparent;background:#F0F6FF;border-radius:18rpx;padding:24rpx 4rpx;font-size:21rpx;font-weight:650}.type-symbol{font-size:38rpx;color:#1680FF;margin-bottom:10rpx}.chosen{border-color:#1677FF;background:#E4F1FF}.tick{position:absolute;right:8rpx;top:4rpx;color:#1677FF}.type-1{background:#FFF0F0}.type-1 .type-symbol{color:#F07878}.type-2{background:#EFFBF8}.type-2 .type-symbol{color:#20BCA9}.type-3{background:#FFF7E7}.type-3 .type-symbol{color:#F2B342}.card .section{font-size:28rpx}</style>
